//! Cargo-driven `msctf.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is msctf-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x71f60000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7fedd000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7fedd000000u64)),
        o => panic!("msctf-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:uuid", "engine:wine", "engine:c:cicero", "import:user32", "import:advapi32", "import:advapi32_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "import:shell32", "import:shlwapi", "import:ole32", "import:oleaut32", "import:imm32", "import:gdi32", "import:comctl32", "engine:oldnames", "engine:delayimp_rust"],
        "x86_64" => &["body", "engine:uuid", "engine:wine", "engine:c:cicero", "import:user32", "import:advapi32", "import:advapi32_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "import:shell32", "import:shlwapi", "import:ole32", "import:oleaut32", "import:imm32", "import:gdi32", "import:comctl32", "engine:oldnames", "engine:delayimp_rust"],
        "aarch64" => &["body", "engine:uuid", "engine:wine", "engine:c:cicero", "import:user32", "import:advapi32", "import:advapi32_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "import:shell32", "import:shlwapi", "import:ole32", "import:oleaut32", "import:imm32", "import:gdi32", "import:comctl32", "engine:oldnames", "engine:delayimp_rust"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/base/ctf/msctf",
        "base/ctf/msctf",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "UNICODE",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_UNICODE",
        "_WIN32_WINNT=0x600",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .rust_staticlib("msctf-rust")
        .c_from_compile_db("msctf_shims", &["base/ctf/msctf/rust_cohab_stub.cpp"])
        .rc("base/ctf/msctf/version.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("base/ctf/msctf/msctf.spec", "msctf.dll")
        .spec_stubs()
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/advapi32_vista/advapi32_vista.spec", "advapi32_vista.dll", "advapi32_vista")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        .delay_import_lib("dll/win32/shell32/shell32.spec", "shell32.dll", "shell32")
        .delay_import_lib("dll/win32/shlwapi/shlwapi.spec", "shlwapi.dll", "shlwapi")
        .delay_import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .delay_import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .delay_import_lib("win32ss/user/imm32/imm32.spec", "imm32.dll", "imm32")
        .delay_import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .delay_import_lib("dll/win32/comctl32/comctl32.spec", "comctl32.dll", "comctl32")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
